:root {
  --fg: #1a1a2e; --muted: #6b7280; --bg: #f7f7fb; --card: #fff;
  --accent: #4f46e5; --danger: #dc2626; --border: #e5e7eb; --base: 15px;
}
:root[data-text-size='large'] { --base: 18px; }

* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
  background: var(--bg); color: var(--fg); font-size: var(--base); }
.app { max-width: 900px; margin: 0 auto; padding: 1rem; }

.topbar { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: .5rem; }
.topbar h1 { font-size: 1.4rem; margin: .3rem 0; }
nav button { background: none; border: none; padding: .4rem .7rem; cursor: pointer; border-radius: 6px; color: var(--muted); font-size: .95em; }
nav button.active { background: var(--accent); color: #fff; }

button { cursor: pointer; border: 1px solid var(--border); background: #fff; border-radius: 6px; padding: .35rem .6rem; font-size: .9em; }
button:hover { border-color: var(--accent); }
button.primary, button.active, .btn { background: var(--accent); color: #fff; border-color: var(--accent); }
button.danger { color: var(--danger); border-color: #f3c2c2; }
.btn { display: inline-block; text-decoration: none; padding: .45rem .8rem; border-radius: 6px; }

.banner { background: #eef2ff; border: 1px solid #c7d2fe; padding: .5rem .8rem; border-radius: 8px; margin: .6rem 0; cursor: pointer; }
.add-box { display: flex; gap: .5rem; margin: 1rem 0; flex-wrap: wrap; }
.add-url { flex: 1; min-width: 220px; padding: .6rem; border: 1px solid var(--border); border-radius: 8px; font-size: 1em; }
.field-error { color: var(--danger); font-size: .85em; width: 100%; }

.toolbar { display: flex; gap: .5rem; margin: .5rem 0; flex-wrap: wrap; }
.search { flex: 1; min-width: 240px; padding: .55rem; border: 1px solid var(--border); border-radius: 8px; }
select { padding: .45rem; border: 1px solid var(--border); border-radius: 8px; }

.saved-searches { display: flex; gap: .4rem; align-items: center; flex-wrap: wrap; margin-bottom: .5rem; }
.saved-chip { display: inline-flex; align-items: center; background: #eef; border-radius: 6px; }
.saved-chip button { border: none; background: none; padding: .25rem .4rem; }

.bulk-bar { display: flex; gap: .4rem; align-items: center; flex-wrap: wrap; background: #fffbe6; border: 1px solid #fde68a; padding: .5rem; border-radius: 8px; margin-bottom: .5rem; }

.list { display: flex; flex-direction: column; gap: .6rem; }
.card { display: grid; grid-template-columns: auto auto 1fr auto; gap: .6rem; align-items: start;
  background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: .7rem; }
.card-selected { outline: 2px solid var(--accent); }
.card-select { margin-top: .3rem; }
.favicon { width: 20px; height: 20px; margin-top: .2rem; }
.card-body { min-width: 0; }
.card-title { font-weight: 600; color: var(--fg); text-decoration: none; }
.card-title:hover { color: var(--accent); text-decoration: underline; }
.card-url { color: var(--muted); font-size: .82em; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.card-desc { font-size: .9em; margin: .25rem 0; }
.card-tags { display: flex; gap: .3rem; flex-wrap: wrap; margin-top: .3rem; align-items: center; }
.preview { width: 90px; height: 60px; object-fit: cover; border-radius: 6px; }
.card-actions { display: flex; flex-direction: column; gap: .25rem; }

.chip { display: inline-flex; align-items: center; gap: .2rem; background: #eef2ff; color: #3730a3; border-radius: 999px; padding: .1rem .5rem; font-size: .78em; border: none; }
.chip-clickable { cursor: pointer; }
.chip-x { background: none; border: none; cursor: pointer; padding: 0 .1rem; color: inherit; }
.badge { font-size: .72em; background: #fef3c7; color: #92400e; border-radius: 4px; padding: .1rem .4rem; }
.badge-archived { background: #e5e7eb; color: #374151; }

.snapshot { margin-top: .4rem; font-size: .82em; display: flex; gap: .8rem; }
.snapshot a { color: var(--accent); text-decoration: none; }
.muted { color: var(--muted); }

.tag-input { position: relative; }
.tag-chips { display: flex; gap: .3rem; flex-wrap: wrap; margin-bottom: .3rem; }
.tag-input input { width: 100%; padding: .4rem; border: 1px solid var(--border); border-radius: 6px; }
.suggestions { position: absolute; z-index: 5; background: #fff; border: 1px solid var(--border); border-radius: 6px; width: 100%; box-shadow: 0 4px 12px rgba(0,0,0,.08); }
.suggestion { display: block; width: 100%; text-align: left; border: none; padding: .4rem .6rem; }

.notes-editor { border: 1px solid var(--border); border-radius: 8px; overflow: hidden; }
.notes-toolbar { display: flex; gap: .2rem; padding: .3rem; background: #fafafa; border-bottom: 1px solid var(--border); }
.notes-toolbar button { padding: .2rem .5rem; }
.notes-surface { min-height: 100px; padding: .6rem; outline: none; }
.notes-surface:empty::before { content: attr(data-placeholder); color: var(--muted); }

.empty { text-align: center; color: var(--muted); padding: 3rem 1rem; }

.panel { background: var(--card); border: 1px solid var(--border); border-radius: 10px; padding: 1rem 1.2rem; }
.panel section { margin: 1rem 0; padding-bottom: 1rem; border-bottom: 1px solid var(--border); }
.panel label { display: block; margin: .8rem 0; }
.panel label.checkbox { display: flex; gap: .5rem; align-items: flex-start; }
.panel select, .panel input[type=text] { margin-left: .5rem; }

.modal-backdrop { position: fixed; inset: 0; background: rgba(0,0,0,.4); display: flex; align-items: center; justify-content: center; padding: 1rem; }
.modal { background: #fff; border-radius: 12px; padding: 1.2rem; width: 100%; max-width: 560px; max-height: 90vh; overflow: auto; }
.modal label { display: block; margin: .6rem 0 .2rem; font-weight: 600; font-size: .9em; }
.modal input { width: 100%; padding: .5rem; border: 1px solid var(--border); border-radius: 6px; }
.modal-actions { display: flex; justify-content: flex-end; gap: .5rem; margin-top: 1rem; }

